(5908859, 861338, 115307, '<td valign="top">So, at first the stars in this image just looked like specks of dust on my screen. Lucky for you, I studied this image a little longer. 8</td>', 'So, at first the stars in this image just looked like specks of dust on my screen. Lucky for you, I studied this image a little longer. 8', '2010-03-17 19:34:53.000000', NULL, 1),
(5908862, 860943, 115307, '<td valign="top">Absolutely gorgeous! Definitely a 10 from me, and I hope this ribbons.<br/>I have seen several firework pictures in my time, but none as colorful and radiant as this one.</td>', 'Absolutely gorgeous! Definitely a 10 from me, and I hope this ribbons.I have seen several firework pictures in my time, but none as colorful and radiant as this one.', '2010-03-17 19:36:16.000000', NULL, 1),
