(5909514, 861028, 107138, '<td valign="top">Way too dark. Please shoot when there is more light.</td>', 'Way too dark. Please shoot when there is more light.', '2010-03-18 10:59:49.000000', NULL, 1),
(5909515, 861336, 107138, '<td valign="top">Too dark. Adjust you shutter speed.</td>', 'Too dark. Adjust you shutter speed.', '2010-03-18 10:59:52.000000', NULL, 1),
(5909518, 860879, 107138, '<td valign="top">Excellent photo. I would adjust your contrast a little though. You could have brought out much more color in this photo. But still its an awesome shot! Good job! Keep up the good work.</td>', 'Excellent photo. I would adjust your contrast a little though. You could have brought out much more color in this photo. But still its an awesome shot! Good job! Keep up the good work.', '2010-03-18 11:01:33.000000', NULL, 1),
(5909544, 860647, 89230, '<td valign="top">Beautiful. Its a shame that there are people in this photo.</td>', 'Beautiful. Its a shame that there are people in this photo.', '2010-03-18 11:52:36.000000', NULL, 1),
(5909547, 861085, 89230, '<td valign="top">I think this is my favorite of the challenge. The only problem I have with it is that there appears a lot of noise in the sky. Either way, nice photo!</td>', 'I think this is my favorite of the challenge. The only problem I have with it is that there appears a lot of noise in the sky. Either way, nice photo!', '2010-03-18 11:54:50.000000', NULL, 1),
(5909548, 860963, 89230, '<td valign="top">Very unique, and very well done!!</td>', 'Very unique, and very well done!!', '2010-03-18 11:54:55.000000', NULL, 1),
(5909549, 861065, 89230, '<td valign="top">So bizarre. Fantastic!!</td>', 'So bizarre. Fantastic!!', '2010-03-18 11:55:21.000000', NULL, 1),
(5909552, 860960, 30861, '<td valign="top">Dang, that takes me back... Way back in the day, we used to camp here. I don''t think that''s allowed anymore? Lovely capture. Probably getting dinged because twilight isn''t "night"? I think that''s what''s happening to me :-(</td>', 'Dang, that takes me back... Way back in the day, we used to camp here. I don''t think that''s allowed anymore? Lovely capture. Probably getting dinged because twilight isn''t "night"? I think that''s what''s happening to me :-(', '2010-03-18 11:56:54.000000', NULL, 1),
(5909572, 861060, 105130, '<td valign="top">I really, really want to give this a high vote, but it looks like it''s been sharpened to death. The artifacts around the bright points of lights are just too distracting.</td>', 'I really, really want to give this a high vote, but it looks like it''s been sharpened to death. The artifacts around the bright points of lights are just too distracting.', '2010-03-18 12:22:17.000000', NULL, 1),
(5909576, 861359, 105130, '<td valign="top">I''m betting that''s the sun. Like the photo though.</td>', 'I''m betting that''s the sun. Like the photo though.', '2010-03-18 12:26:34.000000', NULL, 1),
(5909592, 861340, 23484, '<td valign="top">Gorgeous shot. I like the color and the darkness of the subject. The stars are a neat effect.</td>', 'Gorgeous shot. I like the color and the darkness of the subject. The stars are a neat effect.', '2010-03-18 12:44:41.000000', NULL, 1),
