(5909595, 861264, 23484, '<td valign="top">Nice job. I''ve seen these before.</td>', 'Nice job. I''ve seen these before.', '2010-03-18 12:46:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5909596, 861110, 23484, '<td valign="top">Beautiful shot of the eye. The lighting is perfect.</td>', 'Beautiful shot of the eye. The lighting is perfect.', '2010-03-18 12:46:46.000000', NULL, 1),
(5909615, 861353, 110472, '<td valign="top">Looks great!</td>', 'Looks great!', '2010-03-18 12:57:35.000000', NULL, 1),
(5909656, 860708, 10785, '<td valign="top">This is so perfect for the lensbaby! The pedestrian, the car and the sign, are all in good focus and make for great composition in the selective focus ring. The OOF elements all radiate from the sweet spot forcing your eyes right into the best part of the shot! Sooo Awesome! The noise from ISO doesn''t even matter! I give it a 10!</td>', 'This is so perfect for the lensbaby! The pedestrian, the car and the sign, are all in good focus and make for great composition in the selective focus ring. The OOF elements all radiate from the sweet spot forcing your eyes right into the best part of the shot! Sooo Awesome! The noise from ISO doesn''t even matter! I give it a 10!', '2010-03-18 13:54:59.000000', NULL, 1),
(5909659, 860963, 10785, '<td valign="top">Looks like you have a great transition from night to day. The long exposure time neglects to show the movement of the fan blades too well. It would have been awesome to see a nice motion blur on those.</td>', 'Looks like you have a great transition from night to day. The long exposure time neglects to show the movement of the fan blades too well. It would have been awesome to see a nice motion blur on those.', '2010-03-18 13:57:23.000000', NULL, 1),
(5909666, 860960, 112739, '<td valign="top">Best work yet for this challenge. Great work!</td>', 'Best work yet for this challenge. Great work!', '2010-03-18 14:11:17.000000', NULL, 1),
(5909668, 860943, 112739, '<td valign="top">Great work!</td>', 'Great work!', '2010-03-18 14:12:03.000000', NULL, 1),
(5909684, 860964, 109227, '<td valign="top">Needs a little better focus.</td>', 'Needs a little better focus.', '2010-03-18 14:51:36.000000', NULL, 1),
(5909686, 861086, 109227, '<td valign="top">Would have been better with a little more focus.</td>', 'Would have been better with a little more focus.', '2010-03-18 14:51:51.000000', NULL, 1),
(5909687, 861213, 109227, '<td valign="top">A little overexposed; sign needs to be a little sharper.</td>', 'A little overexposed; sign needs to be a little sharper.', '2010-03-18 14:51:54.000000', NULL, 1),
