(5911051, 861322, 38032, '<td valign="top">Nice shot - I find it hard to believe as a night shot though. It will be interesting to see if others think the same.</td>', 'Nice shot - I find it hard to believe as a night shot though. It will be interesting to see if others think the same.', '2010-03-20 11:49:06.000000', NULL, 1),
(5911059, 861088, 63503, '<td valign="top">This is a WOW!</td>', 'This is a WOW!', '2010-03-20 11:52:10.000000', NULL, 1),
(5911060, 861307, 38032, '<td valign="top">Pretty cool.  It looks like an inverted image though.  A few moments later  So I went in and reversed the image to see what the deal was  Honestly I can''t tell either way so i need to give you the benefit of the doubt. =)</td>', 'Pretty cool.  It looks like an inverted image though.  A few moments later  So I went in and reversed the image to see what the deal was  Honestly I can''t tell either way so i need to give you the benefit of the doubt. =)', '2010-03-20 11:55:16.000000', NULL, 1),
(5911067, 861038, 23484, '<td valign="top">Nice shot. Looks like HDR.</td>', 'Nice shot. Looks like HDR.', '2010-03-20 12:07:03.000000', NULL, 1),
(5911068, 860660, 23484, '<td valign="top">I love this. The mist is great as is the B&amp;W. Great shot. 9</td>', 'I love this. The mist is great as is the B&W. Great shot. 9', '2010-03-20 12:07:49.000000', NULL, 1),
(5911069, 860354, 23484, '<td valign="top">This is a really cool shot but it would have been a little better if it were a little sharper. Nice capture.</td>', 'This is a really cool shot but it would have been a little better if it were a little sharper. Nice capture.', '2010-03-20 12:08:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5911072, 860764, 63503, '<td valign="top">I like this as a picture with a compelling story. I guess it is a setup, if so, your models did a great acting job, their expressions and body languare are convincing, it does not look fake at all. I suspect you will get a bunch of low votes as it is not an eye candy DPC type image, but it is probably the only picture in the challenge with a great story. You made great use of the available light and picked the perfect aperture for a very pleasing dof. My only suggestion would be to crop out a bit of the negative space atop, although some may argue that the big dark sky above adds to the feeling of being stuck in a bad situation. Great job, I hope I am not your only 10.</td>', 'I like this as a picture with a compelling story. I guess it is a setup, if so, your models did a great acting job, their expressions and body languare are convincing, it does not look fake at all. I suspect you will get a bunch of low votes as it is not an eye candy DPC type image, but it is probably the only picture in the challenge with a great story. You made great use of the available light and picked the perfect aperture for a very pleasing dof. My only suggestion would be to crop out a bit of the negative space atop, although some may argue that the big dark sky above adds to the feeling of being stuck in a bad situation. Great job, I hope I am not your only 10.', '2010-03-20 12:14:45.000000', NULL, 1),
(5911085, 861085, 69102, '<td valign="top">my absolute favorite of the challenge; very well shot and a unique take on the category</td>', 'my absolute favorite of the challenge; very well shot and a unique take on the category', '2010-03-20 12:42:56.000000', NULL, 1),
(5911086, 860660, 69102, '<td valign="top">lovely, moody shot</td>', 'lovely, moody shot', '2010-03-20 12:43:56.000000', NULL, 1),
(5911087, 860647, 69102, '<td valign="top">a little too much empty space in the upper-left quadrant for me, but great tones and a cool surreal feel with the tower in the background</td>', 'a little too much empty space in the upper-left quadrant for me, but great tones and a cool surreal feel with the tower in the background', '2010-03-20 12:44:53.000000', NULL, 1),
(5911088, 860243, 69102, '<td valign="top">it is a cool subject, but you need to work on finding some sort of interesting angle to bring something new to the photo and try shooting a little earlier or in different lighting conditions to get better color tones</td>', 'it is a cool subject, but you need to work on finding some sort of interesting angle to bring something new to the photo and try shooting a little earlier or in different lighting conditions to get better color tones', '2010-03-20 12:46:59.000000', NULL, 1),
(5911089, 860916, 69102, '<td valign="top">very nice classic seattle skyline</td>', 'very nice classic seattle skyline', '2010-03-20 12:49:45.000000', NULL, 1),
(5911091, 861163, 69102, '<td valign="top">i really like this - very effective</td>', 'i really like this - very effective', '2010-03-20 12:51:01.000000', NULL, 1),
(5911092, 861091, 69102, '<td valign="top">shot at night, but not really a "night shot"</td>', 'shot at night, but not really a "night shot"', '2010-03-20 12:51:52.000000', NULL, 1),
(5911094, 860955, 69102, '<td valign="top">shot at night, but not really a "night shot"</td>', 'shot at night, but not really a "night shot"', '2010-03-20 12:53:37.000000', NULL, 1),
(5911095, 861322, 69102, '<td valign="top">interesting take on the challenge</td>', 'interesting take on the challenge', '2010-03-20 12:54:05.000000', NULL, 1),
(5911096, 860764, 69102, '<td valign="top">this has a very cinematic feel - you really could have played that aspect up by shooting in landscape</td>', 'this has a very cinematic feel - you really could have played that aspect up by shooting in landscape', '2010-03-20 12:55:07.000000', NULL, 1),
(5911125, 861243, 23317, '<td valign="top">Great choice of temperature.</td>', 'Great choice of temperature.', '2010-03-20 13:57:28.000000', NULL, 1),
(5911127, 861163, 23484, '<td valign="top">Nice shot. I like the ominous feel of the clouds.</td>', 'Nice shot. I like the ominous feel of the clouds.', '2010-03-20 13:57:50.000000', NULL, 1),
(5911129, 860146, 23484, '<td valign="top">Beautiful job on the exposure. Nice compositon.</td>', 'Beautiful job on the exposure. Nice compositon.', '2010-03-20 13:58:22.000000', NULL, 1),
(5911130, 861183, 23317, '<td valign="top">I love the abundance of blue.  One of my top 2.</td>', 'I love the abundance of blue.  One of my top 2.', '2010-03-20 13:58:24.000000', NULL, 1),
(5911131, 861341, 23484, '<td valign="top">That''s cool with the McDonalds in the background.</td>', 'That''s cool with the McDonalds in the background.', '2010-03-20 13:58:47.000000', NULL, 1),
(5911132, 861355, 23317, '<td valign="top">Fantastic contrast, sharpness and lines.</td>', 'Fantastic contrast, sharpness and lines.', '2010-03-20 13:58:53.000000', NULL, 1),
(5911133, 860522, 23317, '<td valign="top">Great choice of subject and well executed.  In my top 5</td>', 'Great choice of subject and well executed.  In my top 5', '2010-03-20 13:59:47.000000', NULL, 1),
(5911134, 860879, 23317, '<td valign="top">I love the uniqueness of your entry.</td>', 'I love the uniqueness of your entry.', '2010-03-20 14:01:46.000000', NULL, 1),
(5911136, 859946, 23317, '<td valign="top">I liked this entry, especially when I first saw it.  I like the grain to display the low level of light (which some may not).  I like the expression on her face.  IMO, the title does not fit the look on the subjects face and that detracted from the positive attributes</td>', 'I liked this entry, especially when I first saw it.  I like the grain to display the low level of light (which some may not).  I like the expression on her face.  IMO, the title does not fit the look on the subjects face and that detracted from the positive attributes', '2010-03-20 14:05:21.000000', NULL, 1),
(5911137, 860891, 23317, '<td valign="top">The numerous photos of the eye took away some appeal due to originality.</td>', 'The numerous photos of the eye took away some appeal due to originality.', '2010-03-20 14:06:49.000000', NULL, 1),
(5911178, 861162, 83313, '<td valign="top">Now I''m going to have the Foreigner song "Urgent" running through my head all day. #!@$%&amp;*!</td>', 'Now I''m going to have the Foreigner song "Urgent" running through my head all day. #!@$%&*!', '2010-03-20 15:56:28.000000', NULL, 1),
(5911184, 860171, 83313, '<td valign="top">A lot of high ISO grain in this. That could be a limitation of the camera you are using. The composition really comes off badly to me, however. The elements of interest are all clustered around the edge of the frame and when my eye tries to follow, it is cut off at frame edge. This draws my eye to the area of noisy, grainy, and uninteresting sky in the middle of the pic. Sorry to be so harsh on it, but I think a low vote deserves some explanation to go with it.</td>', 'A lot of high ISO grain in this. That could be a limitation of the camera you are using. The composition really comes off badly to me, however. The elements of interest are all clustered around the edge of the frame and when my eye tries to follow, it is cut off at frame edge. This draws my eye to the area of noisy, grainy, and uninteresting sky in the middle of the pic. Sorry to be so harsh on it, but I think a low vote deserves some explanation to go with it.', '2010-03-20 16:02:37.000000', NULL, 1),
(5911186, 861050, 83313, '<td valign="top">Is the pink collar supposed to fool me into thinking this is a friendly people-lover?</td>', 'Is the pink collar supposed to fool me into thinking this is a friendly people-lover?', '2010-03-20 16:04:48.000000', NULL, 1),
(5911188, 861336, 83313, '<td valign="top">I like the appearance of the window on the right. Is that a piano, in it? I don''t find the rest of them image holds up as well. My eye just wanders around aimlessly.</td>', 'I like the appearance of the window on the right. Is that a piano, in it? I don''t find the rest of them image holds up as well. My eye just wanders around aimlessly.', '2010-03-20 16:06:08.000000', NULL, 1),
(5911218, 861086, 83313, '<td valign="top">That''s just creepy looking. No doubt the effect you were after.</td>', 'That''s just creepy looking. No doubt the effect you were after.', '2010-03-20 17:02:03.000000', NULL, 1),
(5911222, 861088, 83313, '<td valign="top">I hate to leave this comment, because this image clearly took some thought, effort and patience. You saved with way too much compression and there are obvious artifacts showing around some of the powerlines. No doubt you have lost some clarity in other areas as well. At a 53k file size you had an awful lot of overhead. I''m sure this will do very well and will probably beat my own entry, but without all that compression taking away valuable detail, it would be outstanding. Still worth a vote on the positive side of the scale.</td>', 'I hate to leave this comment, because this image clearly took some thought, effort and patience. You saved with way too much compression and there are obvious artifacts showing around some of the powerlines. No doubt you have lost some clarity in other areas as well. At a 53k file size you had an awful lot of overhead. I''m sure this will do very well and will probably beat my own entry, but without all that compression taking away valuable detail, it would be outstanding. Still worth a vote on the positive side of the scale.', '2010-03-20 17:08:25.000000', NULL, 1),
(5911226, 861341, 83313, '<td valign="top">Grog kneel to maker-of-fire. Offer skins of slain enemies for firemaking secret. Oh, Grog see McDonalds!  Grog not need fire now. Grog thank you anyway.</td>', 'Grog kneel to maker-of-fire. Offer skins of slain enemies for firemaking secret. Oh, Grog see McDonalds!  Grog not need fire now. Grog thank you anyway.', '2010-03-20 17:17:40.000000', NULL, 1),
(5911233, 860518, 83313, '<td valign="top">You may not know it, but you''ve got a <a href="//memory-alpha.org/en/wiki/Horta" rel="nofollow" target="_blank">Horta</a> in your city. It left it''s eggs all over the place.</td>', 'You may not know it, but you''ve got a Horta in your city. It left it''s eggs all over the place.', '2010-03-20 17:20:56.000000', NULL, 1),
(5911234, 861028, 83313, '<td valign="top">Seems pixelated or over sharpened to me somehow. Not sure if that was intentional on your part, or something that happened when you resized and saved.</td>', 'Seems pixelated or over sharpened to me somehow. Not sure if that was intentional on your part, or something that happened when you resized and saved.', '2010-03-20 17:22:31.000000', NULL, 1),
(5911236, 861153, 83313, '<td valign="top">I''ll bet if you recreate this scene for next week''s stop motion challenge, we will find it is a 10 year old Toyota with a stuck accelerator.</td>', 'I''ll bet if you recreate this scene for next week''s stop motion challenge, we will find it is a 10 year old Toyota with a stuck accelerator.', '2010-03-20 17:24:05.000000', NULL, 1),
(5911239, 861213, 83313, '<td valign="top">Ok, I''ve stopped. What should I do now? If I vote, the next pic will come up and I won''t be stopped anymore. <br/> <br/>Hmmm, umm, ladedadeda......<br/>.<br/>.<br/>.<br/>.<br/>.<br/>.<br/>.<br/>I''m still waiting....<br/>.<br/>.<br/>.<br/>.<br/>.<br/>.Zzzzzzzzzz....</td>', 'Ok, I''ve stopped. What should I do now? If I vote, the next pic will come up and I won''t be stopped anymore.  Hmmm, umm, ladedadeda.............I''m still waiting..........Zzzzzzzzzz....', '2010-03-20 17:26:05.000000', NULL, 1),
(5911242, 861060, 83313, '<td valign="top">Agh! Compression artifacts to starboard! Hard to port! <br/> <br/>At 158K file size, you had a lot more overhead available to avoid the effects of compression. Compression kills detail and creates blocky artifacts. Always use the least amount of compression you can get away with and still come in under the challenge limit.</td>', 'Agh! Compression artifacts to starboard! Hard to port!  At 158K file size, you had a lot more overhead available to avoid the effects of compression. Compression kills detail and creates blocky artifacts. Always use the least amount of compression you can get away with and still come in under the challenge limit.', '2010-03-20 17:29:40.000000', NULL, 1),
(5911244, 861061, 28427, '<td valign="top">I wish you would have opened them completely.  On the other hand, with the blinds it has a slight touch of voyeurism.</td>', 'I wish you would have opened them completely.  On the other hand, with the blinds it has a slight touch of voyeurism.', '2010-03-20 17:29:53.000000', NULL, 1),
(5911245, 860163, 83313, '<td valign="top">I think this scene would have worked better for me if the white balance were adjusted to reduce the strong yellow cast from the lights.</td>', 'I think this scene would have worked better for me if the white balance were adjusted to reduce the strong yellow cast from the lights.', '2010-03-20 17:31:40.000000', NULL, 1),
(5911246, 861047, 28427, '<td valign="top">I got fear of heights and I feel it when looking at this photograph.  You''ve succeeded well in showing the depth.</td>', 'I got fear of heights and I feel it when looking at this photograph.  You''ve succeeded well in showing the depth.', '2010-03-20 17:32:45.000000', NULL, 1),
(5911247, 860633, 83313, '<td valign="top">Sorry, there''s just not much here that''s really grabbing my eye. I will admit that night shots are harder than they sound.</td>', 'Sorry, there''s just not much here that''s really grabbing my eye. I will admit that night shots are harder than they sound.', '2010-03-20 17:34:02.000000', NULL, 1),
(5911252, 861213, 28427, '<td valign="top">Not very interesting.  To me that is.  Don''t know what other voters will think of it, but it can''t hold my attention for a very long time.  Sorry.</td>', 'Not very interesting.  To me that is.  Don''t know what other voters will think of it, but it can''t hold my attention for a very long time.  Sorry.', '2010-03-20 17:35:36.000000', NULL, 1),
(5911257, 861251, 28427, '<td valign="top">Nice sky with the cloud.</td>', 'Nice sky with the cloud.', '2010-03-20 17:38:40.000000', NULL, 1),
(5911260, 861293, 28427, '<td valign="top">Perfect sharpness from the front to the back.  Off course, you got help from the architect who decided there would come blue lights underneath each pillar, but you''ve captured it beautifully *9*</td>', 'Perfect sharpness from the front to the back.  Off course, you got help from the architect who decided there would come blue lights underneath each pillar, but you''ve captured it beautifully *9*', '2010-03-20 17:46:18.000000', NULL, 1),
(5911261, 860962, 28427, '<td valign="top">What happened here?? This looks like a photograph taken from a TV-screen??<br/>The right side suffers from overexposure and almost hurts the eye.<br/>I''m sorry I can''t say anything positive, even if I want to, but this is not a great success.</td>', 'What happened here?? This looks like a photograph taken from a TV-screen??The right side suffers from overexposure and almost hurts the eye.I''m sorry I can''t say anything positive, even if I want to, but this is not a great success.', '2010-03-20 17:49:57.000000', NULL, 1),
(5911270, 861073, 28427, '<td valign="top">May I drool? I really envy you (no bad intention) *10*</td>', 'May I drool? I really envy you (no bad intention) *10*', '2010-03-20 18:03:20.000000', NULL, 1),
(5911274, 861077, 28427, '<td valign="top">Great exposure, nicely sharp.  Great photograph *8*</td>', 'Great exposure, nicely sharp.  Great photograph *8*', '2010-03-20 18:05:34.000000', NULL, 1),
(5911276, 861178, 28427, '<td valign="top">I like the softness of the fog over/behind the bridge.</td>', 'I like the softness of the fog over/behind the bridge.', '2010-03-20 18:06:47.000000', NULL, 1),
(5911278, 861150, 28427, '<td valign="top">Did you went up there especially for this photograph? Or is this a view you have nearby your place? If the first is the case: you didn''t spare any effort for this challenge.  If the second option is the case: you live in an amazing environment.</td>', 'Did you went up there especially for this photograph? Or is this a view you have nearby your place? If the first is the case: you didn''t spare any effort for this challenge.  If the second option is the case: you live in an amazing environment.', '2010-03-20 18:08:49.000000', NULL, 1),
(5911283, 860171, 28427, '<td valign="top">The night is not very much showing here.</td>', 'The night is not very much showing here.', '2010-03-20 18:17:25.000000', NULL, 1),
(5911288, 860647, 28427, '<td valign="top">I keep finding this an amazing building... Well captured.</td>', 'I keep finding this an amazing building... Well captured.', '2010-03-20 18:20:29.000000', NULL, 1),
(5911291, 860389, 28427, '<td valign="top">Nice colour play in the reflection</td>', 'Nice colour play in the reflection', '2010-03-20 18:26:51.000000', NULL, 1),
(5911293, 860960, 28427, '<td valign="top">I''m sure your photograph will do well in this entry.  I like it a lot *8*</td>', 'I''m sure your photograph will do well in this entry.  I like it a lot *8*', '2010-03-20 18:29:20.000000', NULL, 1),
(5911346, 861110, 114660, '<td valign="top">Outstanding shot!  Easily gets a 10 from me!</td>', 'Outstanding shot!  Easily gets a 10 from me!', '2010-03-20 20:18:16.000000', NULL, 1),
(5911347, 860916, 114660, '<td valign="top">Great cityscape!  I give it a 10!</td>', 'Great cityscape!  I give it a 10!', '2010-03-20 20:18:40.000000', NULL, 1),
(5911349, 861046, 83313, '<td valign="top">What can I add to the armload of comments you must already have? Ribbon material for sure.</td>', 'What can I add to the armload of comments you must already have? Ribbon material for sure.', '2010-03-20 20:22:18.000000', NULL, 1),
(5911350, 860955, 83313, '<td valign="top">Is this the low voting troll?</td>', 'Is this the low voting troll?', '2010-03-20 20:22:48.000000', NULL, 1),
(5911407, 860308, 37845, '<td valign="top">Beautifully photographed. This ''bean'' is nothing unique to DPC, but the way you shot it definitely is. One of my top picks.</td>', 'Beautifully photographed. This ''bean'' is nothing unique to DPC, but the way you shot it definitely is. One of my top picks.', '2010-03-20 22:07:58.000000', NULL, 1),
(5911573, 860708, 44882, '<td valign="top">I love the ambiance in this shot, well captured.</td>', 'I love the ambiance in this shot, well captured.', '2010-03-21 06:54:40.000000', NULL, 1),
(5911640, 861357, 63750, '<td valign="top">I like the aspect ratio of this, but the black bars at top and bottom are a bit distracting.</td>', 'I like the aspect ratio of this, but the black bars at top and bottom are a bit distracting.', '2010-03-21 10:42:52.000000', NULL, 1),
(5911642, 860912, 63750, '<td valign="top">I like this. The angle of the shot gives some energy to an otherwise very still shot.  Good contrast and tones.</td>', 'I like this. The angle of the shot gives some energy to an otherwise very still shot.  Good contrast and tones.', '2010-03-21 10:45:44.000000', NULL, 1),
(5911643, 861322, 63750, '<td valign="top">Great shot. Wonderful contrast.</td>', 'Great shot. Wonderful contrast.', '2010-03-21 10:47:25.000000', NULL, 1),
(5911652, 859813, 83313, '<td valign="top">Gotta give you a high vote just for having the nerve to enter this. Besides, it''s funny. Not sure though, if it is pointing at the water, or it it is a "thumbs down". If you were going for the brown, I apologize for messing up your plans.</td>', 'Gotta give you a high vote just for having the nerve to enter this. Besides, it''s funny. Not sure though, if it is pointing at the water, or it it is a "thumbs down". If you were going for the brown, I apologize for messing up your plans.', '2010-03-21 10:59:32.000000', NULL, 1),
(5911653, 861107, 83313, '<td valign="top">The tilted horizon is easily fixed in most editing software.</td>', 'The tilted horizon is easily fixed in most editing software.', '2010-03-21 11:00:23.000000', NULL, 1),
(5911654, 860346, 83313, '<td valign="top">The high contrast b/w is a good effort at doing something a little different, though for me this does not seem the shot to use such a treatment on.</td>', 'The high contrast b/w is a good effort at doing something a little different, though for me this does not seem the shot to use such a treatment on.', '2010-03-21 11:02:03.000000', NULL, 1),
(5911656, 861178, 63750, '<td valign="top">I think the foreground trees may be a little over lit here for the picture as a whole.  It may distract a bit from the "fogginess."</td>', 'I think the foreground trees may be a little over lit here for the picture as a whole.  It may distract a bit from the "fogginess."', '2010-03-21 11:05:35.000000', NULL, 1),
(5911657, 861094, 83313, '<td valign="top">Coming off as a very soft snapshot, I''m afraid. There''s a heavy color cast to it and it might have worked better for me with a different white balance adjustment.</td>', 'Coming off as a very soft snapshot, I''m afraid. There''s a heavy color cast to it and it might have worked better for me with a different white balance adjustment.', '2010-03-21 11:05:55.000000', NULL, 1),
(5911661, 859902, 83313, '<td valign="top">Harsh on-camera flash is what ruined this shot for you, I''m afraid. Could have been cool looking if you''d used no flash, a long exposure to get some motion blur, and perhaps lit the skateboarder some other way. Maybe a flashlight illuminating him, or have him hold some lights perhaps.</td>', 'Harsh on-camera flash is what ruined this shot for you, I''m afraid. Could have been cool looking if you''d used no flash, a long exposure to get some motion blur, and perhaps lit the skateboarder some other way. Maybe a flashlight illuminating him, or have him hold some lights perhaps.', '2010-03-21 11:09:49.000000', NULL, 1),
(5911662, 861027, 83313, '<td valign="top">This is the toilet paper factory?</td>', 'This is the toilet paper factory?', '2010-03-21 11:11:15.000000', NULL, 1),
(5911663, 861247, 83313, '<td valign="top">Makes a cool abstract. I''ll have to keep this in mind.</td>', 'Makes a cool abstract. I''ll have to keep this in mind.', '2010-03-21 11:12:25.000000', NULL, 1),
(5911666, 860308, 63750, '<td valign="top">Back to bump.  I think this is a shoe in for the front page - 10.</td>', 'Back to bump.  I think this is a shoe in for the front page - 10.', '2010-03-21 11:15:17.000000', NULL, 1),
(5911667, 861357, 83313, '<td valign="top">A pay phone, how 20th century!</td>', 'A pay phone, how 20th century!', '2010-03-21 11:16:01.000000', NULL, 1),
(5911669, 860964, 83313, '<td valign="top">It is dark at 15:30?</td>', 'It is dark at 15:30?', '2010-03-21 11:18:53.000000', NULL, 1),
(5911677, 861249, 83313, '<td valign="top">Grog say stand back. Grog have sharp pointy stick to kill monster. Grog be famous hero, like Don Quixote. Get picture in paper, have many females to bear Grog''s children. Grog is great.</td>', 'Grog say stand back. Grog have sharp pointy stick to kill monster. Grog be famous hero, like Don Quixote. Get picture in paper, have many females to bear Grog''s children. Grog is great.', '2010-03-21 11:27:07.000000', NULL, 1),
