(5915058, 861075, 81530, '<td valign="top">Great work Brad :)</td>', 'Great work Brad :)', '2010-03-24 00:05:03.000000', NULL, 0),
(5915059, 861046, 37845, '<td valign="top">Congrats on the PB, the 7+ Score, and the ribbon. Well deserved.</td>', 'Congrats on the PB, the 7+ Score, and the ribbon. Well deserved.', '2010-03-24 00:05:12.000000', NULL, 0),
(5915060, 860960, 30861, '<td valign="top">Great job, dude. Aren''t the 5D''s incredible for long exposure? Mine didn''t score as well, sadly, but I had the distinction of hand-holding it in full darkness at ISO 1600 and getting a usable image from it :-)<br/> <br/>Congrats on top 10 with one of my favorite places.</td>', 'Great job, dude. Aren''t the 5D''s incredible for long exposure? Mine didn''t score as well, sadly, but I had the distinction of hand-holding it in full darkness at ISO 1600 and getting a usable image from it :-) Congrats on top 10 with one of my favorite places.', '2010-03-24 00:05:16.000000', NULL, 0),
(5915061, 861365, 113142, '<td valign="top">I know! Too late, I realized the image I had initially selected would have been disqualified for being prior to the challenge announcement, and this was a hastily-chosen-slapped-in-there pic. Poo on me, for shame! for shame!<br/><br/><i>Message edited by author 2010-03-24 00:05:48.</i></td>', 'I know! Too late, I realized the image I had initially selected would have been disqualified for being prior to the challenge announcement, and this was a hastily-chosen-slapped-in-there pic. Poo on me, for shame! for shame!', '2010-03-24 00:05:22.000000', '2010-03-24 00:05:48.000000', 0),
(5915064, 860916, 37845, '<td valign="top">Brent, this is an incredible shot. Congrats on the blue ribbon.</td>', 'Brent, this is an incredible shot. Congrats on the blue ribbon.', '2010-03-24 00:05:38.000000', NULL, 0),
(5915066, 860146, 113634, '<td valign="top">so glad this one did well!  congrats on a great photo!  i am originally from wilkes-barre, but i would have given it a 10 even if i wasn''t....great job!!</td>', 'so glad this one did well!  congrats on a great photo!  i am originally from wilkes-barre, but i would have given it a 10 even if i wasn''t....great job!!', '2010-03-24 00:05:47.000000', NULL, 0),
(5915074, 861085, 104230, '<td valign="top">Congratulations, Ben.  Hey, that middle rock almost looks as if it could be a sleeping beast with its claws protruding into the water.</td>', 'Congratulations, Ben.  Hey, that middle rock almost looks as if it could be a sleeping beast with its claws protruding into the water.', '2010-03-24 00:06:55.000000', NULL, 0),
(5915077, 860325, 61084, '<td valign="top">Strong entry and top 20 to go along with it. Nice job.</td>', 'Strong entry and top 20 to go along with it. Nice job.', '2010-03-24 00:07:22.000000', NULL, 0),
(5915082, 861060, 83313, '<td valign="top">Did quite well in spite of the compression issues. For a change of pace, I wasn''t the only one to see them. I see this made a new PB for you, congrats!</td>', 'Did quite well in spite of the compression issues. For a change of pace, I wasn''t the only one to see them. I see this made a new PB for you, congrats!', '2010-03-24 00:09:56.000000', NULL, 0);
