(5915093, 861046, 66515, '<td valign="top">interesting way of applying zoom blur to the shot. A lot more subtle and effective than other attempts I''ve seen. (especially my own!) Congrats on the ribbon!</td>', 'interesting way of applying zoom blur to the shot. A lot more subtle and effective than other attempts I''ve seen. (especially my own!) Congrats on the ribbon!', '2010-03-24 00:11:45.000000', NULL, 0),
(5915094, 860916, 18799, '<td valign="top">Beautiful!!!<br/> <br/>The one and two (votes) are getting really sickening around here.<br/><br/><i>Message edited by author 2010-03-24 00:12:34.</i></td>', 'Beautiful!!! The one and two (votes) are getting really sickening around here.', '2010-03-24 00:11:58.000000', '2010-03-24 00:12:34.000000', 0),
(5915096, 861085, 30982, '<td valign="top">Gorgeous spot with what looks to be little man-made light to cause issues.  I wanted to shoot here, but there are just too darn many lights in town.  I''ll have to look outside of town up the coast a bit.  Is that the city in the distance?</td>', 'Gorgeous spot with what looks to be little man-made light to cause issues.  I wanted to shoot here, but there are just too darn many lights in town.  I''ll have to look outside of town up the coast a bit.  Is that the city in the distance?', '2010-03-24 00:12:15.000000', NULL, 0),
